package tallyorder

import (
	"errors"
	"fmt"
	"sort"
)

func counts(xs []string) ([]string, map[string]int) {
	var order []string
	m := map[string]int{}
	for _, x := range xs {
		if _, ok := m[x]; !ok {
			order = append(order, x)
		}
		m[x]++
	}
	return order, m
}

func Tally(xs []string) []string {
	order, m := counts(xs)
	out := []string{}
	for _, x := range order {
		out = append(out, fmt.Sprintf("%s=%d", x, m[x]))
	}
	return out
}

func TopTally(xs []string, k int64) ([]string, error) {
	if k < 0 {
		return nil, errors.New("negative k")
	}
	order, m := counts(xs)
	sort.SliceStable(order, func(i, j int) bool { return m[order[i]] > m[order[j]] })
	out := []string{}
	for _, x := range order {
		if int64(len(out)) >= k {
			break
		}
		out = append(out, fmt.Sprintf("%s=%d", x, m[x]))
	}
	return out, nil
}

func ModeAll(xs []string) []string {
	order, m := counts(xs)
	best := 0
	for _, c := range m {
		if c > best {
			best = c
		}
	}
	out := []string{}
	for _, x := range order {
		if m[x] == best {
			out = append(out, x)
		}
	}
	return out
}

func DropDupes(xs []string) []string {
	order, _ := counts(xs)
	if order == nil {
		return []string{}
	}
	return order
}

func Repeated(xs []string) []string {
	seen := map[string]bool{}
	again := map[string]bool{}
	out := []string{}
	for _, x := range xs {
		if seen[x] && !again[x] {
			again[x] = true
			out = append(out, x)
		}
		seen[x] = true
	}
	return out
}

func LastOrder(xs []string) []string {
	last := map[string]int{}
	for i, x := range xs {
		last[x] = i
	}
	out := []string{}
	for x := range last {
		out = append(out, x)
	}
	sort.Slice(out, func(i, j int) bool { return last[out[i]] < last[out[j]] })
	return out
}

