mod common;
use common::Json;
use std::panic::{catch_unwind, AssertUnwindSafe};

trait ToJ {
    fn j(&self) -> Json;
}
impl ToJ for i32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u32 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for u8 {
    fn j(&self) -> Json {
        Json::Int(*self as i64)
    }
}
impl ToJ for i64 {
    fn j(&self) -> Json {
        Json::Int(*self)
    }
}
impl ToJ for bool {
    fn j(&self) -> Json {
        Json::Bool(*self)
    }
}
impl ToJ for String {
    fn j(&self) -> Json {
        Json::Str(self.clone())
    }
}
impl<T: ToJ> ToJ for Vec<T> {
    fn j(&self) -> Json {
        Json::Arr(self.iter().map(|x| x.j()).collect())
    }
}
impl<T: ToJ> ToJ for Option<T> {
    fn j(&self) -> Json {
        match self {
            Some(x) => x.j(),
            None => Json::Null,
        }
    }
}

fn call(f: &str, a: &[Json]) -> Option<Result<Json, ()>> {
    Some(match f {
